import React from 'react';
import './Home.css';

const Home = () => {
  return (
    <div className="home-page">
      <section className="hero">
        <h1>Find your perfect plant</h1>
        <p>Explore our collection of beautiful and healthy plants.</p>
      </section>

      <section className="featured-nurseries">
        <h2>Featured Nurseries</h2>
        <div className="nursery-list">
          {/* Placeholder for nursery items */}
          <div className="nursery-item">Nursery 1</div>
          <div className="nursery-item">Nursery 2</div>
          <div className="nursery-item">Nursery 3</div>
        </div>
      </section>

      <section className="popular-plants">
        <h2>Popular Plants</h2>
        <div className="plant-list">
          {/* Placeholder for plant items */}
          <div className="plant-item">Plant 1</div>
          <div className="plant-item">Plant 2</div>
          <div className="plant-item">Plant 3</div>
          <div className="plant-item">Plant 4</div>
        </div>
      </section>
    </div>
  );
};

export default Home;
